        // 移除整个initThemeToggle函数，因为不再需要模式切换
        // function initThemeToggle() { /* ... */ }

        class RecruitmentRenderer {
            constructor(dataSourceId) {
                this.dataSourceId = dataSourceId;
                this.selectedCandidates = new Set();
                this.maxSelection = 2;
                this.initElements();
            }

            initElements() {
                this.elements = {
                    statusBarTitle: document.getElementById('status-bar-title'), // 这个ID在UI中保留但不再显示“加载中”
                    candidatesContainer: document.getElementById('candidates-container'),
                    confirmButton: document.getElementById('confirm-button'),
                };
            }

            init() {
                try {
                    this.loadYaml();
                    this.renderAll();
                    this.setupEventListeners();
                } catch (error) {
                    this.handleError(error);
                }
            }

            loadYaml() {
                const scriptElement = document.getElementById(this.dataSourceId);
                if (!scriptElement) throw new Error('YAML数据源未找到');
                const yamlContent = scriptElement.textContent.trim();
                if (!yamlContent) { 
                    // 在手机UI模式下，没有数据时显示一个居中的提示
                    this.elements.candidatesContainer.innerHTML = '<div class="text-center text-appSecondaryText p-8">等待AI生成候选人...</div>';
                    // 不再隐藏body，而是让手机框架保持显示
                    return; 
                }
                this.yamlData = jsyaml.load(yamlContent);
                if (!this.yamlData) throw new Error('YAML数据无效');
            }

            renderAll() {
                const rootNodeKey = Object.keys(this.yamlData)[0];
                const rootData = this.yamlData[rootNodeKey];
                // 不再更新statusBarTitle，因为它在新的UI中是固定的
                // this.elements.statusBarTitle.textContent = `招募候选人 - ${rootData['招募主题'] || '请选择'}`; 

                const candidatesListKey = this.findFieldByKeywords(rootData, ['候选人列表']);
                const candidates = candidatesListKey ? rootData[candidatesListKey] : [];
                this.elements.candidatesContainer.innerHTML = ''; // 清空可能存在的“等待中”提示
                candidates.forEach(item => {
                    const candidateKey = this.findFieldByKeywords(item, ['候选人']);
                    const candidateData = candidateKey ? item[candidateKey] : item;
                    const card = this.createCandidateCard(candidateData);
                    if (card) this.elements.candidatesContainer.appendChild(card);
                });
            }

            createCandidateCard(data) {
                if (!data || typeof data !== 'object') return null;

                const nameField = this.findFieldByKeywords(data, ['名字']);
                const candidateName = nameField ? String(data[nameField]).replace(/(\p{Emoji_Presentation}|\p{Extended_Pictographic})/gu, '').trim() : '未知';

                const card = document.createElement('div');
                card.className = 'card bg-appCard rounded-xl p-4 shadow-md theme-transition pink-glow-border space-y-3'; // 适配浅色卡片背景
                card.dataset.name = candidateName;

                const title = document.createElement('h3');
                title.className = 'font-bold text-lg text-appText'; // 适配浅色文本
                title.textContent = candidateName;
                card.appendChild(title);

                const tagsField = this.findFieldByKeywords(data, ['标签']);
                if (tagsField && data[tagsField]) {
                    const tagsContainer = document.createElement('div');
                    tagsContainer.className = 'flex flex-wrap gap-2';
                    const tags = String(data[tagsField]).split('/').map(t => t.trim());
                    tags.forEach(tag => {
                        const tagElement = document.createElement('span');
                        tagElement.className = 'tag bg-primary/15 text-primary text-xs font-semibold px-2 py-1 rounded-full'; // 适配浅色标签
                        tagElement.textContent = tag;
                        tagsContainer.appendChild(tagElement);
                    });
                    card.appendChild(tagsContainer);
                }

                const detailsContainer = document.createElement('div');
                detailsContainer.className = 'text-sm space-y-2';
                const detailFields = ['年龄', '常见穿搭', '情感状况'];
                detailFields.forEach(fieldName => {
                    const fieldKey = this.findFieldByKeywords(data, [fieldName]);
                    if (fieldKey && data[fieldKey]) {
                        const detailElement = document.createElement('p');
                        detailElement.className = 'text-appSecondaryText'; // 适配浅色次要文本
                        detailElement.innerHTML = `<strong class="font-medium text-appText">${fieldName}:</strong> ${data[fieldKey]}`; // 适配浅色文本
                        detailsContainer.appendChild(detailElement);
                    }
                });
                card.appendChild(detailsContainer);

                const bioField = this.findFieldByKeywords(data, ['简介']);
                if (bioField && data[bioField]) {
                    const bioElement = document.createElement('p');
                    bioElement.className = 'text-sm text-appText pt-2 border-t border-appBorder'; // 适配浅色文本和边框
                    bioElement.textContent = data[bioField];
                    card.appendChild(bioElement);
                }

                const quoteField = this.findFieldByKeywords(data, ['代表性发言']);
                if (quoteField && data[quoteField]) {
                    const quoteElement = document.createElement('blockquote');
                    quoteElement.className = 'quote text-sm italic text-appSecondaryText border-l-2 border-pinkGlow/60 pl-3 py-1 bg-pinkGlow/8 rounded'; // 适配浅色引用样式
                    quoteElement.textContent = `“${data[quoteField]}”`;
                    card.appendChild(quoteElement);
                }

                return card;
            }

            setupEventListeners() {
                this.elements.candidatesContainer.addEventListener('click', (e) => {
                    const card = e.target.closest('.card');
                    if (!card) return;
                    const name = card.dataset.name;
                    if (this.selectedCandidates.has(name)) {
                        this.selectedCandidates.delete(name);
                        card.classList.remove('selected');
                    } else {
                        if (this.selectedCandidates.size < this.maxSelection) {
                            this.selectedCandidates.add(name);
                            card.classList.add('selected');
                        }
                    }
                    this.updateConfirmButton();
                });

                this.elements.confirmButton.addEventListener('click', () => {
                    if (this.selectedCandidates.size === 0) return;
                    const names = Array.from(this.selectedCandidates);
                    const message = `我已选择：${names.join('和')} 作为租客入住。`;
                    triggerQuickReply(message);
                    this.elements.confirmButton.textContent = '发送成功!';
                    this.elements.confirmButton.disabled = true;
                });

                this.updateConfirmButton();
            }

            updateConfirmButton() {
                const count = this.selectedCandidates.size;
                if (count === 0) {
                    this.elements.confirmButton.textContent = '请选择租客 (最多2位)';
                    this.elements.confirmButton.disabled = true;
                } else {
                    this.elements.confirmButton.textContent = `确认选择这 ${count} 位租客`;
                    this.elements.confirmButton.disabled = false;
                }
            }

            findFieldByKeywords(data, keywords) {
                if (!data || typeof data !== 'object') return null;
                const fields = Object.keys(data);
                for (const field of fields) {
                    for (const keyword of keywords) {
                        if (String(field).toLowerCase().includes(keyword.toLowerCase())) return field;
                    }
                }
                return null;
            }

            handleError(error) { 
                console.error('渲染错误:', error);
                this.elements.candidatesContainer.innerHTML = `<div class="text-red-500 p-4">加载候选人失败: ${error.message}</div>`;
            }
        }
    </script>
