        .modal-page { position: absolute; top: 0; left: 0; width: 100%; height: 100%; background-color: var(--screen-bg); display: flex; flex-direction: column; transform: translateY(100%); transition: transform 0.4s cubic-bezier(0.25, 1, 0.5, 1); z-index: 20; }
