<script>
    const MAX_RETRIES = 5;
    const RETRY_DELAY = 400;
    let currentRetry = 0;

    function SafeGetValue(data, path, defaultValue = '未知') {
        if (!data) return defaultValue;
        const keys = path.split('.');
        let current = data;
        for (const key of keys) {
            if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(key)) {
                return defaultValue;
            }
            current = current[key];
        }
        if (current === undefined || current === null) return defaultValue;
        if (Array.isArray(current) && current.length > 0) {
            const value = current[0];
            return String(value) === '' ? defaultValue : String(value);
        }
        return String(current) === '' ? defaultValue : String(current);
    }

// 替换原来的 populateData 函数
async function populateData() {
    try {
        if (typeof getChatMessages !== 'function' || typeof getCurrentMessageId !== 'function') { return; }
        const messages = await getChatMessages(getCurrentMessageId());
        const data = messages?.[0]?.data?.stat_data;

        if (!data) {
            if (currentRetry < MAX_RETRIES) {
                currentRetry++;
                setTimeout(populateData, RETRY_DELAY);
            } else {
                const header = document.getElementById('screen-header-time');
                if (header) header.innerText = "未能加载数据喵QAQ";
            }
            return;
        }

        const world = data.世界;
        document.getElementById('screen-header-time').innerText = 
            `${SafeGetValue(world, '年份')}年${SafeGetValue(world, '月份')}月${SafeGetValue(world, '日期')}日 星期${SafeGetValue(world, '星期')} ${SafeGetValue(world, '具体时间')}`;

        // -- 修改开始 --
        // 初始化所有房间名为空
        document.querySelectorAll('.room-name[id]').forEach(el => el.innerText = '空');

        const tenantRecords = data.租客档案;
        if (tenantRecords) {
            const roomOccupants = {}; // 用来存储每个房间的住户列表

            // 1. 收集每个房间的所有住户
for (const key in tenantRecords) {
                const tenant = tenantRecords[key];
                const charName = SafeGetValue(tenant, '角色名');
                const roomID = SafeGetValue(tenant, '房间ID');

                if (charName !== '空' && charName !== '未知' && roomID !== '空' && roomID !== '未知') {
                    if (!roomOccupants[roomID]) {
                        roomOccupants[roomID] = []; // 如果是第一个住户，创建数组
                    }
                    roomOccupants[roomID].push(charName); // 添加住户名到数组
                }
            }

            // 2. 遍历收集到的信息，更新界面
            for (const roomID in roomOccupants) {
                const roomNameEl = document.getElementById(`room_name_${roomID}`);
                if (roomNameEl) {
                    roomNameEl.innerText = roomOccupants[roomID].join(' & ');
                }
            }
        }

    } catch (error) {
        console.error("状态栏加载出错:", error);
        const header = document.getElementById('screen-header-time');
        if (header) header.innerText = "加载出错了!";
    }
}

// 替换原来的 showRoomInfo 函数
window.showRoomInfo = async function(roomID) {
    try {
        const messages = await getChatMessages(getCurrentMessageId());
        const data = messages?.[0]?.data?.stat_data;
        if (!data) return;

        const tenantRecords = data.租客档案;
        const charData = data.角色数据;
        const roomModalPage = document.getElementById('roomModalPage');

        // -- 修改开始 --
        const occupantKeys = []; // 创建一个数组来存储所有住户的Key
        if (tenantRecords) {
            for (const key in tenantRecords) {
                if (SafeGetValue(tenantRecords[key], '房间ID') === roomID && SafeGetValue(tenantRecords[key], '角色名') !== '空') {
                    occupantKeys.push(key); // 找到一个就推进数组，不中断
                }
            }
        }

        if (occupantKeys.length > 0 && charData) {
            let modalTitle = [];
            let modalBodyContent = '';

            // 遍历所有住户，为每个人生成一个信息块
            occupantKeys.forEach((key, index) => {
                if (charData[key]) {
                    const char = charData[key];
                    modalTitle.push(SafeGetValue(char, '姓名')); // 收集名字用于标题

                    // 如果不是第一个人，在信息块之间添加一条分割线
                    if (index > 0) {
                        modalBodyContent += `<hr style="border:0; border-top:1px solid var(--modal-item-border); margin: 20px 0;">`;
                    }

                    // 为当前住户生成HTML内容
                    modalBodyContent += `
                        <h4 style="color: var(--header-color); margin-bottom: 10px; margin-top: 5px;">${SafeGetValue(char, '姓名')} 的状态</h4>
                        <ul>
                            <li><strong>姓名:</strong> <span>${SafeGetValue(char, '姓名')}</span></li>
                            <li><strong>年龄:</strong> <span>${SafeGetValue(char, '年龄')}</span></li>
                            <li><strong>职业:</strong> <span>${SafeGetValue(char, '职业')}</span></li>
                            <li><strong>性格:</strong> <span>${SafeGetValue(char, '性格')}</span></li>
                            <li><strong>恋情:</strong> <span>${SafeGetValue(char, '恋情状态')}</span></li>
                            <li><strong>心情:</strong> <span>${SafeGetValue(char, '心情')}</span></li>
                            <li><strong>状态:</strong> <span>${SafeGetValue(char, '当前状态')}</span></li>
                            <li><strong>❤️ 好感度:</strong> <span>${SafeGetValue(char, '好感度')}/100</span></li>
                            <li style="border:none; padding-bottom:0; padding-top:2px;"><div class="progress-bar-container"><div class="progress-bar heart" style="width: ${SafeGetValue(char, '好感度', 0)}%;"></div></div></li>
                            <li style="padding-top:8px;"><strong>🔥 性欲:</strong> <span>${SafeGetValue(char, '性欲')}/100</span></li>
                            <li style="border:none; padding-bottom:0; padding-top:2px;"><div class="progress-bar-container"><div class="progress-bar fire" style="width: ${SafeGetValue(char, '性欲', 0)}%;"></div></div></li>
                        </ul><hr style="border:0; border-top:1px solid var(--modal-item-border); margin: 15px 0;"><ul>
                            <li><strong>🍒胸部:</strong> <span>${SafeGetValue(char, '胸部')}</span></li>
                            <li><strong>👙内衣:</strong> <span>${SafeGetValue(char, '内衣')}</span></li>
                            <li><strong>🩲内裤:</strong> <span>${SafeGetValue(char, '内裤')}</span></li>
                            <li><strong>🌸小穴:</strong> <span>${SafeGetValue(char, '小穴')}</span></li>
                            <li><strong>🍑肛门:</strong> <span>${SafeGetValue(char, '肛门')}</span></li>
                        </ul>`;
                }
            });

            // 组合最终的弹窗HTML
roomModalPage.innerHTML = `
                <div class="modal-header" onclick="closeModal('roomModalPage')">
                    <h3 class="modal-title">${modalTitle.join(' & ')}</h3><span class="modal-close-icon"></span>
                </div>
                <div class="modal-body"><div class="modal-body-pink">
                    ${modalBodyContent}
                </div></div>`;
            roomModalPage.classList.add('visible');
        }
        // -- 修改结束 --

    } catch (e) { console.error("打开房间信息时出错: ", e); }
}

    window.showTasksModal = async function() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            const data = messages?.[0]?.data?.stat_data;
            if (!data) return;
            const world = data.世界;
            const tasksModalPage = document.getElementById('tasksModalPage');
            tasksModalPage.innerHTML = `
